INSERT INTO `lesson_exam_papers` (`lesson_id`,`exam_paper_id`,`position`,`is_required`,`created_at`,`updated_at`) SELECT l.id,p.id,1,0,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM lessons l JOIN course_sections s ON s.id=l.course_section_id JOIN courses c ON c.id=s.course_id JOIN exam_papers p ON p.slug='ec-grammar-practice-01' WHERE c.code='EC-GRAMMAR' AND l.slug='thi-hien-tai' ON DUPLICATE KEY UPDATE `lesson_id`=`lesson_exam_papers`.`lesson_id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('ec-toeic','TOEIC',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`name`,`slug`,`delivery_mode`,`summary`,`description`,`duration_hours`,`price`,`access_days`,`is_active`,`is_for_sale`,`published_at`,`learning_outcomes`,`created_at`,`updated_at`) SELECT cat.id,'EC-TOEIC-READ','TOEIC Reading cơ bản: thông báo và email','toeic-reading-co-ban','online','Học cách đọc thông báo công việc, tìm thông tin trong email và xử lý câu hỏi ngữ pháp theo ngữ cảnh.','Học cách đọc thông báo công việc, tìm thông tin trong email và xử lý câu hỏi ngữ pháp theo ngữ cảnh.\n\nKhóa mẫu do English Center tự biên soạn. Nội dung học và đề luyện được lưu ngay trong hệ thống. Có ba bài học, bài tập áp dụng và một đề tổng kết gồm sáu câu kèm lời giải. Thanh toán trong bản này là mô phỏng, không thu tiền thật.',3,249000,365,1,1,'2026-10-22 09:50:59','["Tìm được người gửi, mục đích và thời hạn trong email.","Đọc chính xác giờ, địa điểm và thay đổi trong thông báo.","Chọn từ dựa vào cấu trúc và nghĩa của câu."]','2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='ec-toeic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `course_sections` (`course_id`,`title`,`position`,`created_at`,`updated_at`) SELECT c.id,'Lộ trình học và thực hành',1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM courses c WHERE c.code='EC-TOEIC-READ' ON DUPLICATE KEY UPDATE `id`=`course_sections`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Đọc thông báo: ai, ở đâu, khi nào','doc-thong-bao','MỤC TIÊU\nRút ra thông tin chính trong một thông báo ngắn.\n\nQUY TRÌNH\nĐọc tiêu đề để đoán chủ đề. Đọc câu hỏi để biết cần tìm giờ, địa điểm hay người nhận. Sau đó quét các từ khóa tương ứng trong văn bản. Đừng chọn một con số chỉ vì nó xuất hiện; hãy xác định con số đó nói về việc gì.\n\nVĂN BẢN THỰC HÀNH\n‘Office notice: The weekly planning meeting has moved from Tuesday to Thursday. It will begin at 9:30 a.m. in Room 204. Please send agenda suggestions to Ms. Le by Wednesday noon.’\n\nPHÂN TÍCH\nCuộc họp chuyển sang Thursday, không còn Tuesday. 9:30 a.m. là giờ bắt đầu. Wednesday noon là hạn gửi đề xuất, không phải thời gian họp. Ms. Le là người nhận đề xuất; văn bản không nói cô ấy chủ trì cuộc họp.\n\nTHỰC HÀNH\nViết ba câu trả lời: cuộc họp diễn ra ngày nào; ở đâu; hạn gửi đề xuất là khi nào?\n\nĐÁP ÁN\nThursday; Room 204; Wednesday noon. Khi ôn lại, đánh dấu câu chứa chứng cứ cho mỗi đáp án.',1,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-TOEIC-READ' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Đọc email theo mục đích giao tiếp','doc-email','MỤC TIÊU\nXác định mục đích email và việc người nhận cần làm.\n\nCÁCH ĐỌC\nDòng subject thường nêu chủ đề. Đoạn đầu giải thích lý do viết. Các từ please, could you, remember to thường dẫn tới yêu cầu. Các từ by, before, no later than chỉ hạn chót.\n\nEMAIL THỰC HÀNH\n‘Subject: Updated delivery date\nDear Mr. Nguyen,\nYour order will arrive on Friday instead of Wednesday because of scheduled maintenance at our warehouse. Please reply by 4 p.m. today if the new date is inconvenient. We apologize for the change.\nBest regards,\nCustomer Service’\n\nPHÂN TÍCH\nMục đích chính là thông báo thay đổi ngày giao hàng. Ngày mới là Friday; Wednesday là ngày cũ. Người nhận chỉ cần trả lời trước 4 p.m. nếu ngày mới không thuận tiện. Không suy ra đơn bị hủy hoặc phải trả thêm tiền vì email không nói vậy.\n\nTHỰC HÀNH\nTóm tắt email bằng tiếng Việt trong hai câu, giữ đủ ngày giao mới và điều kiện cần phản hồi.\n\nGỢI Ý\nĐơn sẽ tới thứ Sáu do kho bảo trì. Nếu lịch mới không thuận tiện, người nhận cần trả lời trước 4 giờ chiều hôm nay.',2,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-TOEIC-READ' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Ngữ pháp trong ngữ cảnh và đề luyện','ngu-phap-email','MỤC TIÊU\nDùng cấu trúc câu để chọn từ trong ngữ cảnh công việc.\n\n1. Danh từ và tính từ\nSau một tính từ thường cần danh từ: ‘an important announcement’. Trước danh từ có thể dùng tính từ: ‘a convenient location’. Đừng chỉ chọn từ có nghĩa quen thuộc; kiểm tra vị trí ngữ pháp.\n\n2. Trạng từ\nTrạng từ có thể bổ nghĩa cho động từ: ‘Please read the instructions carefully’. Carefully diễn tả cách đọc, còn careful thường bổ nghĩa danh từ hoặc đi sau be.\n\n3. Giới từ thời gian\nBy Friday chỉ hạn chót không muộn hơn thứ Sáu. On Friday chỉ sự việc xảy ra vào thứ Sáu. At 9:30 dùng cho giờ cụ thể.\n\nTHỰC HÀNH\nChọn dạng đúng: 1. Please respond (quick / quickly). 2. The new office is in a (convenient / conveniently) location. 3. Submit the form (by / at) Monday.\n\nĐÁP ÁN\n1. quickly bổ nghĩa respond. 2. convenient bổ nghĩa location. 3. by chỉ hạn nộp.\n\nLàm đề luyện bên dưới. Các văn bản được biên soạn cho khóa này, không phải đề thi TOEIC chính thức.',3,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-TOEIC-READ' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
